<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
class Booking extends Model { use SoftDeletes; protected $guarded=[]; protected $casts=['function_date'=>'date:Y-m-d','base_amount'=>'float','final_amount'=>'float','price_per_leaf'=>'float','additional_charges'=>'float','discount'=>'float']; public function customer(){return $this->belongsTo(Customer::class);} public function package(){return $this->belongsTo(SadyaPackage::class,'sadya_package_id');} public function menuItems(){return $this->hasMany(BookingMenuItem::class);} public function payments(){return $this->hasMany(Payment::class);} public function expenses(){return $this->hasMany(Expense::class);} public function getPaidAmountAttribute(){$in=$this->payments->where('direction','in')->sum('amount');$out=$this->payments->where('direction','out')->sum('amount');return (float)($in-$out);} public function getBalanceAmountAttribute(){return max(0,$this->final_amount-$this->paid_amount);} public function getEstimatedProfitAttribute(){return $this->final_amount-(float)$this->expenses->sum('amount');} }
